// Shared 256-bit key, loaded once at startup.
const KEY = loadKeyFromKms();

// A single fixed nonce, generated once when the module loads.
const NONCE = crypto.randomBytes(12); // 96-bit, looks random -> looks safe

function encrypt(plaintext) {
  const cipher = crypto.createCipheriv('aes-256-gcm', KEY, NONCE);
  const ct = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();
  return { ct, tag }; // NONCE is constant, so we don't even send it
}

// Every message this process encrypts uses the SAME (KEY, NONCE) pair.
